from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]

def presentation_credit():
    return '<div class="presentation-credit"><span>Website concept by <a href="https://ayosgawa.com/" target="_blank" rel="noopener">AyosGawa</a> <span aria-hidden="true">/</span> <a href="https://princereyes.com/" target="_blank" rel="noopener">Prince Reyes</a></span><a href="backoffice.html">Explore the CMS &amp; CRM demo →</a></div>'

def write_entity(filename, key, name, strapline, mark, profile, nav, content):
    links = ''.join(f'<a href="#{target}">{label}</a>' for target, label in nav)
    head = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Independent {escape(strapline)} website prototype and local request builder."><meta name="theme-color" content="#0b1c2d"><title>{escape(name)} {escape(strapline)} | Independent service website</title><link rel="stylesheet" href="site.css?v=backoffice-1"><link rel="stylesheet" href="studio.css?v=backoffice-1"><link rel="stylesheet" href="entity.css?v=backoffice-1"><script>try{{document.documentElement.dataset.theme=localStorage.getItem('callueng-{key}-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}}catch{{}}</script><script src="site.js?v=backoffice-1" defer></script><script src="entity.js?v=backoffice-1" defer></script></head><body class="entity-{key}" data-entity="{key}"><a class="skip" href="#main">Skip to content</a><header class="site-header entity-header"><div class="header-inner"><a class="brand entity-brand" href="{filename}" aria-label="{escape(name)} home"><span class="entity-mark" aria-hidden="true">{mark}</span><span><strong>{escape(name)}</strong><small>{escape(strapline)}</small></span></a><nav class="main-nav" id="main-nav" aria-label="Business navigation">{links}<a href="{profile}" target="_blank" rel="noopener">Contact this business</a></nav><div class="header-actions"><button class="icon-button" type="button" data-theme aria-label="Switch colour theme"><img class="icon" src="assets/moon.svg" alt="" width="20" height="20"></button><button class="icon-button menu-toggle" type="button" data-menu aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false"><img class="icon" src="assets/menu-2.svg" alt="" width="20" height="20"></button></div></div></header><main id="main">'''
    foot = f'''</main><footer class="entity-footer"><div class="container"><div><h3>{escape(name)}</h3><p>{escape(strapline)} · Antipolo</p><p>Independent business website prototype. Requests are prepared locally; contact this provider to confirm scope, price, availability, and fulfilment. Nothing is uploaded, booked, ordered, or paid.</p><a class="text-link" href="{profile}" target="_blank" rel="noopener">Visit this business on Facebook<img class="icon" src="assets/arrow-up-right.svg" alt="" width="20" height="20"></a></div><nav aria-label="Other independent website prototypes"><strong>Other business websites</strong><a href="index.html">W.V. Callueng Construction</a><a href="blueprinting.html">W.V. Callueng Blueprinting Services</a><a href="site-support.html">Callueng Hardware, Rentals &amp; Hauling</a></nav></div></footer></body></html>'''
    foot = foot.replace('</nav></div></footer>', '</nav>'+presentation_credit()+'</div></footer>')
    (ROOT / filename).write_text(head + content + foot, encoding='utf-8')
